import React, { useState, useEffect, useCallback } from 'react';
import { Joyride, STATUS, EVENTS } from 'react-joyride';

/* ── Tour steps (o'zbek tilida) ─────────────────────────────── */
const STEPS = [
  {
    target: 'body',
    placement: 'center',
    disableBeacon: true,
    content: (
      <TooltipCard
        emoji="👋"
        title="BitePlate'ga xush kelibsiz!"
        accent="indigo"
        desc={
          <>
            Bu yerda siz restoran ish jarayonining <b>barcha bosqichlarini</b> boshqarasiz —
            stol egallashdan tortib, to'lov chekigacha.
            <br /><br />
            Keling, tizimni birga ko'rib chiqaylik! <br />
            <span className="text-indigo-400 font-semibold">5 daqiqa vaqtingizni olamiz.</span>
          </>
        }
        step="Boshlash"
        total={9}
        current={1}
      />
    ),
  },
  {
    target: '#tour-sidebar',
    placement: 'right',
    disableBeacon: true,
    content: (
      <TooltipCard
        emoji="🗂️"
        title="Asosiy Menyu"
        accent="indigo"
        desc={
          <>
            Chap tarafdagi menyu orqali tizimning barcha bo'limlariga o'tasiz:
            <ul className="mt-2 space-y-1">
              <li className="flex items-center gap-2"><span className="text-emerald-400">🍽️</span> <b>Stollar</b> — stol boshqaruvi</li>
              <li className="flex items-center gap-2"><span className="text-amber-400">🔥</span> <b>Oshxona</b> — buyurtmalar navbati</li>
              <li className="flex items-center gap-2"><span className="text-blue-400">📊</span> <b>Statistika</b> — daromad tahlili</li>
              <li className="flex items-center gap-2"><span className="text-purple-400">👥</span> <b>Xodimlar</b> — rol va ruxsatlar</li>
            </ul>
          </>
        }
        step="2-qadam"
        total={9}
        current={2}
      />
    ),
  },
  {
    target: '#tour-tables-grid',
    placement: 'top',
    disableBeacon: true,
    content: (
      <TooltipCard
        emoji="🟢"
        title="Stol holatlari"
        accent="emerald"
        desc={
          <>
            Har bir stol o'z holatiga qarab <b>rang bilan belgilanadi</b>:
            <div className="mt-2 space-y-1.5">
              <StatusRow color="emerald" label="Bo'sh" desc="Mijoz o'tirishi mumkin" />
              <StatusRow color="amber"   label="Egallangan" desc="Mijoz taom yeyapti" />
              <StatusRow color="purple"  label="Hisob kutmoqda" desc="To'lov kutilmoqda" />
              <StatusRow color="blue"    label="Band" desc="Oldindan bron qilingan" />
            </div>
          </>
        }
        step="3-qadam"
        total={9}
        current={3}
      />
    ),
  },
  {
    target: '#tour-seat-btn',
    placement: 'top',
    disableBeacon: true,
    content: (
      <TooltipCard
        emoji="🪑"
        title="Mijoz o'tqazish"
        accent="emerald"
        desc={
          <>
            Bo'sh stoldagi <b>"Mijoz o'tqazish"</b> tugmasini bosing.
            Ochilgan formada:
            <ol className="mt-2 space-y-1 list-decimal list-inside text-gray-400">
              <li>Mijoz ismini kiriting</li>
              <li>Xizmat ko'rsatuvchi xodimni tanlang</li>
              <li>"Tasdiqlash" tugmasini bosing</li>
            </ol>
            <div className="mt-2 p-2 bg-emerald-500/10 rounded-lg text-emerald-400 text-xs">
              💡 Stol holati avtomatik "Egallangan"ga o'zgaradi
            </div>
          </>
        }
        step="4-qadam"
        total={9}
        current={4}
      />
    ),
  },
  {
    target: '#tour-order-btn',
    placement: 'top',
    disableBeacon: true,
    content: (
      <TooltipCard
        emoji="🍽️"
        title="Buyurtma berish"
        accent="amber"
        desc={
          <>
            Stol egallangandan so'ng <b>"Buyurtma berish"</b> tugmasini bosing.
            <div className="mt-2 space-y-1.5">
              <FeatureRow icon="📂" text="Kategoriyalar bo'yicha menyu" />
              <FeatureRow icon="➕" text="Taomni bosib savatga qo'shish" />
              <FeatureRow icon="🔢" text="+/- tugmalar bilan miqdor o'zgartirish" />
              <FeatureRow icon="⚠️" text="Allergen ogohlantirishlari" />
              <FeatureRow icon="📤" text="Oshxonaga yuborish" />
            </div>
          </>
        }
        step="5-qadam"
        total={9}
        current={5}
      />
    ),
  },
  {
    target: '#tour-nav-kitchen',
    placement: 'right',
    disableBeacon: true,
    content: (
      <TooltipCard
        emoji="🔥"
        title="Oshxona boshqaruvi"
        accent="amber"
        desc={
          <>
            <b>Oshxona</b> bo'limida buyurtmalarni 3 bosqichda boshqarasiz:
            <div className="mt-3 flex gap-2">
              <KanbanStep color="blue"    label="Navbatda"        icon="⏳" />
              <span className="text-gray-600 mt-6">→</span>
              <KanbanStep color="amber"   label="Tayyorlanmoqda"  icon="🔥" />
              <span className="text-gray-600 mt-6">→</span>
              <KanbanStep color="emerald" label="Tayyor"          icon="✅" />
            </div>
            <div className="mt-2 p-2 bg-amber-500/10 rounded-lg text-amber-400 text-xs">
              💡 "Ortga qaytarish" tugmasi oxirgi amalni bekor qiladi (Command Pattern)
            </div>
          </>
        }
        step="6-qadam"
        total={9}
        current={6}
      />
    ),
  },
  {
    target: '#tour-bill-btn',
    placement: 'top',
    disableBeacon: true,
    content: (
      <TooltipCard
        emoji="🧾"
        title="Hisob-kitob va Chek"
        accent="violet"
        desc={
          <>
            <b>"Hisob-kitob"</b> tugmasini bosib to'lovni rasmiylashtirasiz:
            <div className="mt-2 space-y-1.5">
              <FeatureRow icon="💰" text="4 ta narxlash usuli (chegirmalar)" />
              <FeatureRow icon="💳" text="Chayqa foizini qo'shish" />
              <FeatureRow icon="👥" text="Hisob mehrmon soniga taqsimlash" />
              <FeatureRow icon="🧾" text="Fiskal chek avtomatik chiqadi" />
              <FeatureRow icon="🖨️" text="Chekni chop etish imkoni" />
            </div>
          </>
        }
        step="7-qadam"
        total={9}
        current={7}
      />
    ),
  },
  {
    target: '#tour-nav-history',
    placement: 'right',
    disableBeacon: true,
    content: (
      <TooltipCard
        emoji="📊"
        title="Statistika va Tahlil"
        accent="blue"
        desc={
          <>
            <b>Statistika</b> sahifasida menejer uchun to'liq hisobot:
            <div className="mt-2 space-y-1.5">
              <FeatureRow icon="💵" text="Jami daromad va o'rtacha hisob" />
              <FeatureRow icon="🏆" text="TOP-5 eng ommabop taomlar" />
              <FeatureRow icon="📈" text="Kategoriya bo'yicha daromad grafigi" />
              <FeatureRow icon="📋" text="Barcha to'lovlar tarixi" />
            </div>
            <div className="mt-2 p-2 bg-blue-500/10 rounded-lg text-blue-400 text-xs">
              💡 Ma'lumotlar Singleton Design Pattern orqali saqlanadi
            </div>
          </>
        }
        step="8-qadam"
        total={9}
        current={8}
      />
    ),
  },
  {
    target: 'body',
    placement: 'center',
    disableBeacon: true,
    content: (
      <TooltipCard
        emoji="🎉"
        title="Tayyor! Boshlashingiz mumkin"
        accent="emerald"
        desc={
          <>
            Siz BitePlate tizimidan foydalanishni o'rgandingiz!
            <div className="mt-3 p-3 bg-emerald-500/10 border border-emerald-500/20 rounded-xl space-y-1">
              <p className="text-emerald-400 font-semibold text-xs mb-2">Eslatma:</p>
              <p className="text-gray-400 text-xs">📚 <b>Qo'llanma</b> sahifasida batafsil ma'lumot mavjud</p>
              <p className="text-gray-400 text-xs">🔄 Turni qayta boshlash uchun <b>"Tour"</b> tugmasini bosing</p>
              <p className="text-gray-400 text-xs">❓ Savol bo'lsa, FAQ bo'limini ko'ring</p>
            </div>
          </>
        }
        step="Tugatish"
        total={9}
        current={9}
      />
    ),
  },
];

/* ── Tooltip components ────────────────────────── */
function TooltipCard({ emoji, title, desc, accent, step, total, current }) {
  const accents = {
    indigo:  { bar: 'from-indigo-500 to-violet-500',  badge: 'bg-indigo-500/20 text-indigo-300' },
    emerald: { bar: 'from-emerald-500 to-teal-500',   badge: 'bg-emerald-500/20 text-emerald-300' },
    amber:   { bar: 'from-amber-500 to-orange-500',   badge: 'bg-amber-500/20 text-amber-300' },
    violet:  { bar: 'from-violet-500 to-purple-500',  badge: 'bg-violet-500/20 text-violet-300' },
    blue:    { bar: 'from-blue-500 to-cyan-500',      badge: 'bg-blue-500/20 text-blue-300' },
  };
  const a = accents[accent] || accents.indigo;
  return (
    <div style={{ minWidth: 300, maxWidth: 340 }}>
      {/* Progress bar */}
      <div className="h-1 rounded-t-2xl overflow-hidden">
        <div className={`h-full bg-gradient-to-r ${a.bar}`} style={{ width: `${(current / total) * 100}%`, transition: 'width 0.4s ease' }} />
      </div>

      <div className="p-5">
        {/* Badge + emoji */}
        <div className="flex items-center justify-between mb-3">
          <span className={`badge ${a.badge} border border-white/10`}>{step} / {total}</span>
          <span className="text-2xl">{emoji}</span>
        </div>

        <h3 className="text-white font-bold text-base mb-2">{title}</h3>
        <div className="text-gray-400 text-sm leading-relaxed">{desc}</div>
      </div>
    </div>
  );
}

function StatusRow({ color, label, desc }) {
  const c = { emerald: 'bg-emerald-500', amber: 'bg-amber-500', purple: 'bg-purple-500', blue: 'bg-blue-500' };
  return (
    <div className="flex items-center gap-2 text-xs">
      <div className={`w-2.5 h-2.5 rounded-full ${c[color]} shrink-0`} />
      <span className="text-white font-medium">{label}</span>
      <span className="text-gray-600">—</span>
      <span className="text-gray-400">{desc}</span>
    </div>
  );
}

function FeatureRow({ icon, text }) {
  return (
    <div className="flex items-start gap-2 text-xs text-gray-400">
      <span className="shrink-0 text-sm">{icon}</span>
      <span>{text}</span>
    </div>
  );
}

function KanbanStep({ color, label, icon }) {
  const c = { blue: 'border-blue-500/30 bg-blue-500/10 text-blue-400', amber: 'border-amber-500/30 bg-amber-500/10 text-amber-400', emerald: 'border-emerald-500/30 bg-emerald-500/10 text-emerald-400' };
  return (
    <div className={`flex flex-col items-center gap-1 p-2 rounded-lg border ${c[color]} flex-1 text-center`}>
      <span className="text-lg">{icon}</span>
      <span className="text-[9px] font-semibold">{label}</span>
    </div>
  );
}

/* ── Joyride custom tooltip renderer ──────────── */
function JoyrideTooltip({ continuous, index, isLastStep, step, backProps, closeProps, primaryProps, skipProps, tooltipProps }) {
  return (
    <div {...tooltipProps} style={{ outline: 'none' }}>
      {step.content}
      {/* Buttons row */}
      <div className="flex items-center justify-between px-5 pb-5 gap-3">
        {index > 0 && (
          <button {...backProps} className="btn btn-sm btn-ghost text-xs">← Orqaga</button>
        )}
        <div className="flex gap-2 ml-auto">
          {!isLastStep && (
            <button {...skipProps} className="btn btn-sm btn-ghost text-xs text-gray-600">O'tkazib yuborish</button>
          )}
          <button
            {...primaryProps}
            className={`btn btn-sm ${isLastStep ? 'btn-success' : 'btn-primary'}`}
          >
            {isLastStep ? '🎉 Tugatish' : "Keyingi →"}
          </button>
        </div>
      </div>
    </div>
  );
}

/* ── Main TourGuide component ─────────────────── */
export default function TourGuide({ onTourEnd }) {
  const [run, setRun] = useState(false);
  const [stepIndex, setStepIndex] = useState(0);

  useEffect(() => {
    const seen = localStorage.getItem('bp_tour_done');
    if (!seen) {
      setTimeout(() => setRun(true), 800);
    }
  }, []);

  const handleJoyrideCallback = useCallback((data) => {
    const { status, type, index } = data;
    if ([STATUS.FINISHED, STATUS.SKIPPED].includes(status)) {
      localStorage.setItem('bp_tour_done', '1');
      setRun(false);
      setStepIndex(0);
      onTourEnd?.();
    } else if (type === EVENTS.STEP_AFTER || type === EVENTS.TARGET_NOT_FOUND) {
      setStepIndex(index + 1);
    }
  }, [onTourEnd]);

  return (
    <>
      <Joyride
        steps={STEPS}
        run={run}
        stepIndex={stepIndex}
        continuous
        showSkipButton
        disableScrolling={false}
        disableOverlayClose={false}
        spotlightPadding={8}
        tooltipComponent={JoyrideTooltip}
        callback={handleJoyrideCallback}
        styles={{
          options: {
            arrowColor: '#0f1420',
            backgroundColor: '#0f1420',
            overlayColor: 'rgba(0,0,0,0.75)',
            primaryColor: '#6366f1',
            zIndex: 9999,
          },
          spotlight: {
            borderRadius: 16,
            boxShadow: '0 0 0 3px rgba(99,102,241,0.4), 0 0 0 9999px rgba(0,0,0,0.75)',
          },
        }}
      />

      {/* Floating "Tour" restart button */}
      {!run && (
        <button
          id="tour-restart-btn"
          onClick={() => { setStepIndex(0); setRun(true); }}
          className="fixed bottom-6 right-6 z-50 flex items-center gap-2 px-4 py-2.5 rounded-full
                     bg-indigo-600 hover:bg-indigo-500 text-white text-sm font-semibold
                     shadow-xl shadow-indigo-900/50 transition-all hover:scale-105 active:scale-95"
          title="Yo'riqnomani qayta boshlash"
        >
          <span className="text-base">🎯</span> Tour
        </button>
      )}
    </>
  );
}
